const COURSE_LESSON_HTML = {
  "kurssArticlesLesson": "\n  <h3>Artikeller</h3>\n\n  <div class=\"artikuli-info artikuli-intro-info\">\n    <span class=\"artikuli-info-icon\">i</span>\n    <div>Türkçede dilbilgisel cinsiyet yoktur, bu yüzden Almanca artikeli kelimenin anlamından tahmin etmek her zaman mümkün değildir. Bu nedenle isimleri en iyi artikelleriyle birlikte öğren.</div>\n  </div>\n\n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>•</span>Artikel örnekleri</h4>\n    <div class=\"artikuli-grid\">\n      <div class=\"kurss-example\">der Tisch — masa</div>\n      <div class=\"kurss-example\">die Tür — kapı</div>\n      <div class=\"kurss-example\">das Messer — bıçak</div>\n      <div class=\"kurss-example\">das Mädchen — kız</div>\n    </div>\n  </section>\n\n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>♂</span>Genellikle DER</h4>\n    <p class=\"artikuli-explain\">DER genellikle erkek kişiler, günler, aylar, mevsimler ve belirli eklerle biten bazı kelimeler için kullanılır.</p>\n\n    <h5 class=\"artikuli-subtitle\">Kurallar</h5>\n    <div class=\"artikuli-grid\">\n      <div class=\"kurss-example\">-er → genellikle DER, örneğin: der Computer, der Lehrer <span class=\"artikuli-note\">ama her zaman değil</span></div>\n      <div class=\"kurss-example\">-ling → genellikle DER, örneğin: der Schmetterling</div>\n      <div class=\"kurss-example\">-ismus → genellikle DER, örneğin: der Tourismus, der Kapitalismus</div>\n      <div class=\"kurss-example\">erkek kişiler → der Mann, der Vater</div>\n      <div class=\"kurss-example\">meslekler → der Lehrer, der Arzt</div>\n      <div class=\"kurss-example\">otomobil markaları → der BMW, der Mercedes</div>\n      <div class=\"kurss-example\">günler → der Montag, der Dienstag</div>\n      <div class=\"kurss-example\">aylar → der August, der Dezember</div>\n      <div class=\"kurss-example\">mevsimler → der Sommer, der Winter</div>\n    </div>\n\n    <h5 class=\"artikuli-subtitle\">Örnekler</h5>\n    <div class=\"artikuli-grid\">\n      <div class=\"kurss-example\">der Mann — adam</div>\n      <div class=\"kurss-example\">der Vater — baba</div>\n      <div class=\"kurss-example\">der Montag — pazartesi</div>\n      <div class=\"kurss-example\">der August — ağustos</div>\n      <div class=\"kurss-example\">der Sommer — yaz</div>\n      <div class=\"kurss-example\">der Lehrer — öğretmen</div>\n      <div class=\"kurss-example\">der Computer — bilgisayar</div>\n      <div class=\"kurss-example\">der Schmetterling — kelebek</div>\n    </div>\n  </section>\n\n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>♀</span>Genellikle DIE</h4>\n    <p class=\"artikuli-explain\">DIE genellikle kadın kişiler, çoğul ve -ung, -heit, -keit, -schaft, -ion, -tät, -ei ekleriyle biten kelimeler için kullanılır.</p>\n\n    <h5 class=\"artikuli-subtitle\">Kurallar</h5>\n    <div class=\"artikuli-grid\">\n      <div class=\"kurss-example\">-ung → die Wohnung, die Rechnung</div>\n      <div class=\"kurss-example\">-heit → die Freiheit, die Gesundheit</div>\n      <div class=\"kurss-example\">-keit → die Möglichkeit</div>\n      <div class=\"kurss-example\">-schaft → die Mannschaft</div>\n      <div class=\"kurss-example\">-ion → die Nation</div>\n      <div class=\"kurss-example\">-tät → die Universität</div>\n      <div class=\"kurss-example\">-ei → die Polizei, die Bäckerei</div>\n      <div class=\"kurss-example\">kadın kişiler → die Frau, die Mutter</div>\n      <div class=\"kurss-example\">motosiklet markaları → die Harley-Davidson, die Yamaha</div>\n      <div class=\"kurss-example\">çoğul → die Autos, die Häuser</div>\n      <div class=\"kurss-example\">çoğul neredeyse her zaman → die Autos, die Häuser, die Kinder</div>\n    </div>\n\n    <h5 class=\"artikuli-subtitle\">Örnekler</h5>\n    <div class=\"artikuli-grid\">\n      <div class=\"kurss-example\">die Frau — kadın</div>\n      <div class=\"kurss-example\">die Mutter — anne</div>\n      <div class=\"kurss-example\">die Wohnung — daire</div>\n      <div class=\"kurss-example\">die Rechnung — fatura / hesap</div>\n      <div class=\"kurss-example\">die Freiheit — özgürlük</div>\n      <div class=\"kurss-example\">die Möglichkeit — imkân / olanak</div>\n      <div class=\"kurss-example\">die Mannschaft — takım</div>\n      <div class=\"kurss-example\">die Nation — ulus</div>\n      <div class=\"kurss-example\">die Universität — üniversite</div>\n      <div class=\"kurss-example\">die Polizei — polis</div>\n    </div>\n  </section>\n\n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>◇</span>Genellikle DAS</h4>\n    <p class=\"artikuli-explain\">DAS genellikle -chen / -lein ekli küçültme isimleri, -ment / -um ile biten birçok kelime ve isim olarak kullanılan fiiller için kullanılır.</p>\n\n    <h5 class=\"artikuli-subtitle\">Kurallar</h5>\n    <div class=\"artikuli-grid\">\n      <div class=\"kurss-example\">-chen → das Mädchen, das Häuschen</div>\n      <div class=\"kurss-example\">-lein → das Fräulein</div>\n      <div class=\"kurss-example\">-ment → das Instrument</div>\n      <div class=\"kurss-example\">-um → das Zentrum, das Museum</div>\n      <div class=\"kurss-example\">metaller → das Gold, das Silber, das Eisen</div>\n      <div class=\"kurss-example\">kimyasal elementler → das Eisen, das Kupfer</div>\n      <div class=\"kurss-example\">oteller → das Hotel</div>\n      <div class=\"kurss-example\">isim olarak renkler → das Rot, das Blau</div>\n      <div class=\"kurss-example\">isim olarak fiil → das Essen, das Lernen</div>\n      <div class=\"kurss-example\">isim olarak fiiller → das Essen, das Lernen, das Lesen</div>\n    </div>\n\n    <h5 class=\"artikuli-subtitle\">Örnekler</h5>\n    <div class=\"artikuli-grid\">\n      <div class=\"kurss-example\">das Kind — çocuk</div>\n      <div class=\"kurss-example\">das Mädchen — kız</div>\n      <div class=\"kurss-example\">das Häuschen — küçük ev</div>\n      <div class=\"kurss-example\">das Instrument — enstrüman / alet</div>\n      <div class=\"kurss-example\">das Zentrum — merkez</div>\n      <div class=\"kurss-example\">das Museum — müze</div>\n      <div class=\"kurss-example\">das Essen — yemek yeme / yemek</div>\n      <div class=\"kurss-example\">das Lernen — öğrenme</div>\n    </div>\n  </section>\n\n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>!</span>Önemli istisnalar / artikeliyle öğrenilmesi gerekenler</h4>\n    <p class=\"artikuli-explain\">Bazı kelimelerin artikeli ekinden ya da Türkçedeki anlamından güvenilir şekilde çıkarılamaz. Bunları en iyi artikelleriyle birlikte öğren.</p>\n    <div class=\"artikuli-grid\">\n      <div class=\"kurss-example\">die Tür — kapı</div>\n      <div class=\"kurss-example\">das Messer — bıçak</div>\n      <div class=\"kurss-example\">die Sonne — güneş</div>\n      <div class=\"kurss-example\">der Mond — ay</div>\n      <div class=\"kurss-example\">das Mädchen — kız</div>\n      <div class=\"kurss-example\">das Auto — otomobil</div>\n      <div class=\"kurss-example\">der Käse — peynir</div>\n      <div class=\"kurss-example\">die Gabel — çatal</div>\n    </div>\n  </section>\n\n  <div class=\"artikuli-info artikuli-bottom-info\">\n    <span class=\"artikuli-info-icon\">i</span>\n    <div>Ekler ve kelime grupları artikeli tahmin etmeye yardımcı olur, ancak %100 kesin kurallar değildir. Emin değilsen kelimeyi artikeliyle birlikte öğren.</div>\n  </div>\n",
  "kurssPronounsLesson": "\n  <h3>Zamirler</h3>\n            <div class=\"artikuli-info artikuli-intro-info\">\n    <span class=\"artikuli-info-icon\">i</span>\n    <div>Nominativ, Akkusativ ve Dativ — zamir biçimleri.</div>\n  </div>\n\n            \n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>N</span>Nominativ — kim/ne?</h4>\n    <div class=\"artikuli-grid\"><div class=\"kurss-example\">ich — ben</div><div class=\"kurss-example\">du — sen</div><div class=\"kurss-example\">er — o (eril)</div><div class=\"kurss-example\">sie — o (dişil)</div><div class=\"kurss-example\">es — o (nötr)</div><div class=\"kurss-example\">wir — biz</div><div class=\"kurss-example\">ihr — siz</div><div class=\"kurss-example\">sie — onlar</div><div class=\"kurss-example\">Sie — Siz (resmî)</div></div>\n  </section>\n\n            \n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>A</span>Akkusativ — kimi/neyi?</h4>\n    <div class=\"artikuli-grid\"><div class=\"kurss-example\">mich — beni</div><div class=\"kurss-example\">dich — seni</div><div class=\"kurss-example\">ihn — onu (eril)</div><div class=\"kurss-example\">sie — onu (dişil)</div><div class=\"kurss-example\">es — onu (nötr)</div><div class=\"kurss-example\">uns — bizi</div><div class=\"kurss-example\">euch — sizi</div><div class=\"kurss-example\">sie — onları</div><div class=\"kurss-example\">Sie — Sizi (resmî)</div></div>\n  </section>\n\n            \n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>D</span>Dativ — kime?</h4>\n    <div class=\"artikuli-grid\"><div class=\"kurss-example\">mir — bana</div><div class=\"kurss-example\">dir — sana</div><div class=\"kurss-example\">ihm — ona (eril / nötr)</div><div class=\"kurss-example\">ihr — ona (dişil)</div><div class=\"kurss-example\">uns — bize</div><div class=\"kurss-example\">euch — size</div><div class=\"kurss-example\">ihnen — onlara</div><div class=\"kurss-example\">Ihnen — Size (resmî)</div></div>\n  </section>\n\n            \n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>?</span>Hangi biçim nasıl seçilir?</h4>\n    <ul class=\"kurss-summary-list\"><li><span class=\"case-blue\">Nominativ</span> — özne (kim yapıyor?)</li><li><span class=\"case-red\">Akkusativ</span> — doğrudan nesne (kimi/neyi?)</li><li><span class=\"case-green\">Dativ</span> — dolaylı nesne (kime?)</li></ul>\n  </section>\n\n            \n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>•</span>Örnekler</h4>\n    <div class=\"artikuli-grid\"><div class=\"kurss-example\">Ich sehe <span class=\"case-red\">dich</span>. — Seni görüyorum.</div><div class=\"kurss-example\">Ich sehe <span class=\"case-red\">ihn</span>. — Onu görüyorum.</div><div class=\"kurss-example\">Wir mögen <span class=\"case-red\">euch</span>. — Sizi seviyoruz.</div><div class=\"kurss-example\">Ich helfe <span class=\"case-green\">dir</span>. — Sana yardım ediyorum.</div><div class=\"kurss-example\">Ich gebe <span class=\"case-green\">ihm</span> ein Buch. — Ona bir kitap veriyorum.</div><div class=\"kurss-example\">Wir danken <span class=\"case-green\">euch</span>. — Size teşekkür ediyoruz.</div></div>\n  </section>\n\n  <div class=\"artikuli-info artikuli-bottom-info\">\n    <span class=\"artikuli-info-icon\">i</span>\n    <div>Nominativ her zaman cümlenin öznesidir, Akkusativ ve Dativ ise nesnelerdir. Fiile bak ve sor: <span class=\"case-red\">kimi/neyi?</span> veya <span class=\"case-green\">kime?</span></div>\n  </div>\n",
  "kurssPronunciationLesson": "\n            <h3>Ünlü harfler — uzun ve kısa</h3>\n            <p class=\"kurss-lesson-intro\">Almancada ünlüler uzun ya da kısa olabilir. Bu, kelimenin telaffuzunu etkiler.</p>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Uzun ünlü</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">warm (varm) — sıcak / ılık</div><div class=\"kurss-example\">gut (gût) — iyi</div><div class=\"kurss-example\">Tat (tât) — eylem / iş</div><div class=\"kurss-example\">Flur (flûr) — koridor</div><div class=\"kurss-example\">Weg (vêk) — yol</div><div class=\"kurss-example\">Hut (hût) — şapka</div><div class=\"kurss-example\">Hof (hôf) — avlu</div><div class=\"kurss-example\">Schlaf (şlâf) — uyku</div></div>\n              <p>Ünlüden sonra tek bir ünsüz geliyorsa, ünlü çoğu zaman uzun okunur.</p>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Kısa ünlü</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Pilz (pilts) — mantar</div><div class=\"kurss-example\">Wort (vort) — kelime / söz</div><div class=\"kurss-example\">Mund (munt) — ağız</div><div class=\"kurss-example\">bald (balt) — yakında</div><div class=\"kurss-example\">scharf (şarf) — keskin / acı</div><div class=\"kurss-example\">Feld (felt) — tarla</div><div class=\"kurss-example\">voll (fol) — dolu</div></div>\n              <p>Ünlüden sonra iki veya daha fazla ünsüz geliyorsa, ünlü çoğu zaman kısa okunur.</p>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>en / el / er sonları</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">singen (zingen) — şarkı söylemek</div><div class=\"kurss-example\">tragen (trâgen) — taşımak</div><div class=\"kurss-example\">Garten (garten) — bahçe</div><div class=\"kurss-example\">Vogel (fôgel) — kuş</div><div class=\"kurss-example\">Segel (zêgel) — yelken</div><div class=\"kurss-example\">Braten (brâten) — kızartma (et)</div><div class=\"kurss-example\">Bogen (bôgen) — yay / kemer</div><div class=\"kurss-example\">Spiegel (şpîgel) — ayna</div><div class=\"kurss-example\">Finger (finger) — parmak</div><div class=\"kurss-example\">Halter (halter) — tutucu</div><div class=\"kurss-example\">Arbeiter (arbayter) — işçi</div><div class=\"kurss-example\">Häuser (hoyzer) — evler</div><div class=\"kurss-example\">wieder (vîder) — yine / tekrar</div><div class=\"kurss-example\">breiter (brayter) — daha geniş</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Uzatma işareti olarak h harfi</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Rahmen (râmen) — çerçeve</div><div class=\"kurss-example\">Ohr (ôr) — kulak</div><div class=\"kurss-example\">Kohle (kôle) — kömür</div><div class=\"kurss-example\">Zahl (tsâl) — sayı</div><div class=\"kurss-example\">ihn (în) — onu (eril)</div><div class=\"kurss-example\">ihm (îm) — ona (eril)</div><div class=\"kurss-example\">Huhn (hûn) — tavuk</div><div class=\"kurss-example\">nahm (nâm) — aldı</div><div class=\"kurss-example\">nehmen (nêmen) — almak</div><div class=\"kurss-example\">Schuh (şû) — ayakkabı</div></div>\n              <p>Bazı kelimelerde h, kendinden önceki ünlüyü uzatır. Bu durumlarda h genellikle okunmaz.</p>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>e ile biten sonlar</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Lampe (lampe) — lamba</div><div class=\"kurss-example\">Hase (hâze) — tavşan</div><div class=\"kurss-example\">Knabe (knâbe) — oğlan çocuk</div><div class=\"kurss-example\">Rabe (râbe) — kuzgun</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Uzun i = ie</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">die (dî) — “die” artikeli</div><div class=\"kurss-example\">diese (dîze) — bu / bunlar</div><div class=\"kurss-example\">wieder (vîder) — yine / tekrar</div><div class=\"kurss-example\">Fliege (flîge) — sinek</div><div class=\"kurss-example\">Ziege (tsîge) — keçi</div><div class=\"kurss-example\">Stiel (ştîl) — sap</div><div class=\"kurss-example\">Dieb (dîp) — hırsız</div><div class=\"kurss-example\">hier (hîr) — burada</div></div>\n              <p>Almancada uzun i çoğu zaman ie olarak yazılır.</p>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Çift ünlüler</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Saal (zâl) — salon</div><div class=\"kurss-example\">Saat (zât) — ekim / tohum</div><div class=\"kurss-example\">Staat (ştât) — devlet</div><div class=\"kurss-example\">Beere (bêre) — küçük meyve (çilek, böğürtlen vb.)</div><div class=\"kurss-example\">See (zê) — göl / deniz</div><div class=\"kurss-example\">Beet (bêt) — tarh</div><div class=\"kurss-example\">Boot (bôt) — tekne</div><div class=\"kurss-example\">Moor (môr) — bataklık</div><div class=\"kurss-example\">Moos (môs) — yosun</div></div>\n              <p>Çift ünlüler genellikle uzun okunur.</p>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>ä</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Wand (vant) — duvar</div><div class=\"kurss-example\">Wände (vende) — duvarlar</div><div class=\"kurss-example\">Vater (fâter) — baba</div><div class=\"kurss-example\">Väter (fêter) — babalar</div><div class=\"kurss-example\">Schrank (şrank) — dolap</div><div class=\"kurss-example\">Schränke (şrenke) — dolaplar</div><div class=\"kurss-example\">Bank (bank) — bank (oturak) / banka</div><div class=\"kurss-example\">Bänke (benke) — banklar (oturaklar)</div><div class=\"kurss-example\">Tal (tâl) — vadi</div><div class=\"kurss-example\">Täler (têler) — vadiler</div></div>\n              <p>ä, a harfinin umlautlu (inceltilmiş) biçimidir.</p>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>ö</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Rose (rôze) — gül</div><div class=\"kurss-example\">Röschen (rös-hen) — küçük gül</div><div class=\"kurss-example\">Ofen (ôfen) — fırın / soba</div><div class=\"kurss-example\">Öfen (öfen) — fırınlar / sobalar</div><div class=\"kurss-example\">Rock (rok) — etek</div><div class=\"kurss-example\">Röcke (röke) — etekler</div></div>\n              <p>ö, o harfinin umlautlu (inceltilmiş) biçimidir.</p>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>ü</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">kurz (kurts) — kısa</div><div class=\"kurss-example\">kürzer (kürtser) — daha kısa</div><div class=\"kurss-example\">Kunst (kunst) — sanat</div><div class=\"kurss-example\">Künste (künste) — sanatlar</div><div class=\"kurss-example\">Mutter (muter) — anne</div><div class=\"kurss-example\">Mütter (müter) — anneler</div></div>\n              <p>ü, u harfinin umlautlu (inceltilmiş) biçimidir.</p>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>İkili ünlüler (diftonglar): äu</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Baum (baum) — ağaç</div><div class=\"kurss-example\">Bäume (boyme) — ağaçlar</div><div class=\"kurss-example\">Haus (haus) — ev</div><div class=\"kurss-example\">Häuser (hoyzer) — evler</div><div class=\"kurss-example\">Strauch (ştrauh) — çalı</div><div class=\"kurss-example\">Sträucher (ştroyher) — çalılar</div><div class=\"kurss-example\">Maus (maus) — fare</div><div class=\"kurss-example\">Mäuse (moyze) — fareler</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>İkili ünlüler (diftonglar): eu</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">heute (hoyte) — bugün</div><div class=\"kurss-example\">Leute (loyte) — insanlar</div><div class=\"kurss-example\">neu (noy) — yeni</div><div class=\"kurss-example\">neun (noyn) — dokuz</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>İkili ünlüler (diftonglar): ei</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">mein (mayn) — benim</div><div class=\"kurss-example\">dein (dayn) — senin</div><div class=\"kurss-example\">sein (zayn) — onun (eril / nötr) / olmak</div><div class=\"kurss-example\">frei (fray) — özgür / serbest</div><div class=\"kurss-example\">arbeiten (arbayten) — çalışmak</div></div>\n            </section>\n            <section class=\"kurss-lesson-section\">\n              <h4>2. dersin telaffuz notları</h4>\n              <ul class=\"kurss-summary-list\"><li>ich, nicht, rechnen, zeichnen kelimelerinde “ch” yumuşak okunur</li><li>arbeiten ve zeichnen kelimelerinde “ei”, “ay” gibi okunur</li><li>“sp” kelime başında “şp” gibi okunur</li><li>tun fiilinde “u” harfi uzun okunur</li></ul>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Özet</h4>\n              <ul class=\"kurss-summary-list\"><li>ünlüden sonra tek ünsüz → çoğu zaman uzun ünlü</li><li>iki veya daha fazla ünsüz → çoğu zaman kısa ünlü</li><li>h ünlüyü uzatabilir</li><li>ie çoğu zaman uzun i demektir</li><li>çift ünlüler genellikle uzundur</li></ul>\n            </section>",
  "kurssConsonantsLesson": "\n            <h3>Ünsüzler ve harf kombinasyonları</h3>\n            <p class=\"kurss-lesson-intro\">Almancada bazı ünsüzler ve harf kombinasyonları yazıldıklarından farklı okunur. Bu derste yeni başlayanlar için en önemli örnekler yer alıyor.</p>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Ünsüzler</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">das Rad (rât) — tekerlek</div><div class=\"kurss-example\">die Räder (rêder) — tekerlekler</div><div class=\"kurss-example\">Bad (bât) — banyo / küvet</div><div class=\"kurss-example\">Bäder (bêder) — banyolar / küvetler</div></div>\n              <p>Kelime sonunda ünsüzler çoğu zaman yazıldıkları gibi okunmaz.</p>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>ch</h4>\n              <p>“ch” yumuşak ya da sert okunabilir. Bazı kelimelerde ince bir “h” gibi, bazılarında ise “k”ya yakın, gırtlaktan gelen kalın bir “h” gibi duyulur.</p>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">rechnen (rehnen) — hesaplamak</div><div class=\"kurss-example\">zeichnen (tsayhnen) — çizmek</div><div class=\"kurss-example\">nicht (niht) — değil</div><div class=\"kurss-example\">schlecht (şleht) — kötü</div><div class=\"kurss-example\">mich (mih) — beni</div><div class=\"kurss-example\">dich (dih) — seni</div><div class=\"kurss-example\">Strauch (ştrauh) — çalı</div><div class=\"kurss-example\">noch (noh) — hâlâ / daha</div><div class=\"kurss-example\">Nacht (naht) — gece</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>sch</h4>\n              <p>“sch” Almancada Türkçedeki “ş” gibi okunur.</p>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Schule (şûle) — okul</div><div class=\"kurss-example\">Schüler (şüler) — öğrenci</div><div class=\"kurss-example\">Schiff (şif) — gemi</div><div class=\"kurss-example\">Schraube (şraube) — vida</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Kelime başında sp ve st</h4>\n              <p>Kelime veya hece başında “sp” çoğu zaman “şp”, “st” ise “şt” gibi okunur.</p>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">spielen (şpîlen) — oynamak / çalmak</div><div class=\"kurss-example\">Sprung (şprung) — sıçrayış / atlayış</div><div class=\"kurss-example\">stehen (ştêen) — ayakta durmak</div><div class=\"kurss-example\">Stall (ştal) — ahır</div><div class=\"kurss-example\">Stand (ştant) — durum / yer</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>qu</h4>\n              <p>“qu” Almancada genellikle “kv” gibi okunur.</p>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Qual (kvâl) — eziyet / ıstırap</div><div class=\"kurss-example\">Quartier (kvartîr) — konaklama yeri / semt</div><div class=\"kurss-example\">quer (kvêr) — çapraz / enine</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>s ve z</h4>\n              <p>Kelime başında “s” çoğu zaman “z” gibi duyulur. Almancada “z” harfi “ts” gibi okunur.</p>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">sagen (zâgen) — söylemek</div><div class=\"kurss-example\">singen (zingen) — şarkı söylemek</div><div class=\"kurss-example\">Rose (rôze) — gül</div><div class=\"kurss-example\">Zahl (tsâl) — sayı</div><div class=\"kurss-example\">Zeit (tsayt) — zaman</div><div class=\"kurss-example\">Zink (tsink) — çinko</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>v</h4>\n              <p>Almancada “v” çoğu zaman “f” gibi okunur. Yabancı kökenli kelimelerde ise genellikle Türkçedeki “v” gibi duyulur.</p>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Vater (fâter) — baba</div><div class=\"kurss-example\">von (fon) — -den / -dan</div><div class=\"kurss-example\">viel (fîl) — çok</div><div class=\"kurss-example\">vier (fîr) — dört</div><div class=\"kurss-example\">Villa (villa) — villa</div><div class=\"kurss-example\">Klavier (klavîr) — piyano</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>x ve y</h4>\n              <p>“x” “ks” gibi okunur. “y” bazı kelimelerde “ü” gibi okunur.</p>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Felix (fêliks) — Feliks</div><div class=\"kurss-example\">Axt (akst) — balta</div><div class=\"kurss-example\">Mystik (müstik) — mistisizm</div><div class=\"kurss-example\">Mythe (müte) — mit / efsane</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>ß</h4>\n              <p>“ß” Almancada “s” gibi okunur.</p>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Fuß (fûs) — ayak</div><div class=\"kurss-example\">Füße (füse) — ayaklar</div><div class=\"kurss-example\">Grüße (grüse) — selamlar</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Özet</h4>\n              <ul class=\"kurss-summary-list\"><li>sch → ş</li><li>başta sp / st → şp / şt</li><li>qu → kv</li><li>z → ts</li><li>v çoğu zaman → f</li><li>x → ks</li><li>ß → s</li></ul>\n            </section>",
  "kurssVerbBasicsLesson": "\n            <h3>Fiillerin temelleri</h3>\n            <p class=\"kurss-lesson-intro\">1. dersin fiilleri ve çekimleri (konjugasyon)</p>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Fiiller</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">kommen — gelmek</div><div class=\"kurss-example\">gehen — gitmek</div><div class=\"kurss-example\">stehen — ayakta durmak</div><div class=\"kurss-example\">singen — şarkı söylemek</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>kommen</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">ich komme — ben geliyorum</div><div class=\"kurss-example\">du kommst — sen geliyorsun</div><div class=\"kurss-example\">er kommt — o geliyor</div><div class=\"kurss-example\">sie kommt — o geliyor</div><div class=\"kurss-example\">wir kommen — biz geliyoruz</div><div class=\"kurss-example\">ihr kommt — siz geliyorsunuz</div><div class=\"kurss-example\">sie kommen — onlar geliyorlar</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>gehen</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">ich gehe — ben gidiyorum</div><div class=\"kurss-example\">du gehst — sen gidiyorsun</div><div class=\"kurss-example\">er geht — o gidiyor</div><div class=\"kurss-example\">sie geht — o gidiyor</div><div class=\"kurss-example\">wir gehen — biz gidiyoruz</div><div class=\"kurss-example\">ihr geht — siz gidiyorsunuz</div><div class=\"kurss-example\">sie gehen — onlar gidiyorlar</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>stehen</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">ich stehe — ben ayakta duruyorum</div><div class=\"kurss-example\">du stehst — sen ayakta duruyorsun</div><div class=\"kurss-example\">er steht — o ayakta duruyor</div><div class=\"kurss-example\">sie steht — o ayakta duruyor</div><div class=\"kurss-example\">wir stehen — biz ayakta duruyoruz</div><div class=\"kurss-example\">ihr steht — siz ayakta duruyorsunuz</div><div class=\"kurss-example\">sie stehen — onlar ayakta duruyorlar</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>singen</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">ich singe — ben şarkı söylüyorum</div><div class=\"kurss-example\">du singst — sen şarkı söylüyorsun</div><div class=\"kurss-example\">er singt — o şarkı söylüyor</div><div class=\"kurss-example\">sie singt — o şarkı söylüyor</div><div class=\"kurss-example\">wir singen — biz şarkı söylüyoruz</div><div class=\"kurss-example\">ihr singt — siz şarkı söylüyorsunuz</div><div class=\"kurss-example\">sie singen — onlar şarkı söylüyorlar</div></div>\n            </section>\n            <section class=\"kurss-lesson-section\">\n              <h4>2. dersin fiilleri</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">spielen — oynamak</div><div class=\"kurss-example\">arbeiten — çalışmak</div><div class=\"kurss-example\">fragen — sormak</div><div class=\"kurss-example\">antworten — cevap vermek</div><div class=\"kurss-example\">rechnen — hesaplamak</div><div class=\"kurss-example\">zeichnen — çizmek</div><div class=\"kurss-example\">tun — yapmak</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>spielen</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">ich spiele — ben oynuyorum</div><div class=\"kurss-example\">du spielst — sen oynuyorsun</div><div class=\"kurss-example\">er spielt — o oynuyor</div><div class=\"kurss-example\">sie spielt — o oynuyor</div><div class=\"kurss-example\">wir spielen — biz oynuyoruz</div><div class=\"kurss-example\">ihr spielt — siz oynuyorsunuz</div><div class=\"kurss-example\">sie spielen — onlar oynuyorlar</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>arbeiten</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">ich arbeite — ben çalışıyorum</div><div class=\"kurss-example\">du arbeitest — sen çalışıyorsun</div><div class=\"kurss-example\">er arbeitet — o çalışıyor</div><div class=\"kurss-example\">sie arbeitet — o çalışıyor</div><div class=\"kurss-example\">wir arbeiten — biz çalışıyoruz</div><div class=\"kurss-example\">ihr arbeitet — siz çalışıyorsunuz</div><div class=\"kurss-example\">sie arbeiten — onlar çalışıyorlar</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>fragen</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">ich frage — ben soruyorum</div><div class=\"kurss-example\">du fragst — sen soruyorsun</div><div class=\"kurss-example\">er fragt — o soruyor</div><div class=\"kurss-example\">sie fragt — o soruyor</div><div class=\"kurss-example\">wir fragen — biz soruyoruz</div><div class=\"kurss-example\">ihr fragt — siz soruyorsunuz</div><div class=\"kurss-example\">sie fragen — onlar soruyorlar</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>antworten</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">ich antworte — ben cevap veriyorum</div><div class=\"kurss-example\">du antwortest — sen cevap veriyorsun</div><div class=\"kurss-example\">er antwortet — o cevap veriyor</div><div class=\"kurss-example\">sie antwortet — o cevap veriyor</div><div class=\"kurss-example\">wir antworten — biz cevap veriyoruz</div><div class=\"kurss-example\">ihr antwortet — siz cevap veriyorsunuz</div><div class=\"kurss-example\">sie antworten — onlar cevap veriyorlar</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>rechnen</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">ich rechne — ben hesaplıyorum</div><div class=\"kurss-example\">du rechnest — sen hesaplıyorsun</div><div class=\"kurss-example\">er rechnet — o hesaplıyor</div><div class=\"kurss-example\">sie rechnet — o hesaplıyor</div><div class=\"kurss-example\">wir rechnen — biz hesaplıyoruz</div><div class=\"kurss-example\">ihr rechnet — siz hesaplıyorsunuz</div><div class=\"kurss-example\">sie rechnen — onlar hesaplıyorlar</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>zeichnen</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">ich zeichne — ben çiziyorum</div><div class=\"kurss-example\">du zeichnest — sen çiziyorsun</div><div class=\"kurss-example\">er zeichnet — o çiziyor</div><div class=\"kurss-example\">sie zeichnet — o çiziyor</div><div class=\"kurss-example\">wir zeichnen — biz çiziyoruz</div><div class=\"kurss-example\">ihr zeichnet — siz çiziyorsunuz</div><div class=\"kurss-example\">sie zeichnen — onlar çiziyorlar</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>tun</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">ich tue — ben yapıyorum</div><div class=\"kurss-example\">du tust — sen yapıyorsun</div><div class=\"kurss-example\">er tut — o yapıyor</div><div class=\"kurss-example\">sie tut — o yapıyor</div><div class=\"kurss-example\">wir tun — biz yapıyoruz</div><div class=\"kurss-example\">ihr tut — siz yapıyorsunuz</div><div class=\"kurss-example\">sie tun — onlar yapıyorlar</div></div>\n            </section>",
  "kurssSentenceStructureLesson": "\n            <h3>Cümle yapısı</h3>\n            <p class=\"kurss-lesson-intro\">Almancada soru cümlesinde fiil genellikle birinci sırada yer alır.</p>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Örnekler</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Du kommst. — Sen geliyorsun.</div><div class=\"kurss-example\">Kommst du? — Geliyor musun?</div><div class=\"kurss-example\">Er singt. — O şarkı söylüyor.</div><div class=\"kurss-example\">Singt er? — Şarkı söylüyor mu?</div><div class=\"kurss-example\">Stehst du? — Ayakta mısın?</div><div class=\"kurss-example\">Ja, ich stehe. — Evet, ayaktayım.</div><div class=\"kurss-example\">Geht ihr? — Gidiyor musunuz?</div><div class=\"kurss-example\">Ja, wir gehen. — Evet, gidiyoruz.</div></div>\n            </section>\n            <section class=\"kurss-lesson-section\">\n              <h4>“was” ile sorular</h4>\n              <p>Soru bir soru sözcüğüyle başlıyorsa, Almancada fiil genellikle soru sözcüğünden hemen sonra gelir.</p>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Was tust du? — Ne yapıyorsun?</div><div class=\"kurss-example\">Was tut er? — O ne yapıyor?</div><div class=\"kurss-example\">Was tut sie? — O ne yapıyor?</div><div class=\"kurss-example\">Was tun sie? — Onlar ne yapıyor?</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>“nicht” ile olumsuzluk</h4>\n              <p>Olumsuzluk sözcüğü “nicht” fiile ilişkinse, Almancada genellikle fiilden sonra gelir.</p>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Ich spiele nicht. — Oynamıyorum.</div><div class=\"kurss-example\">Paul fragt nicht. — Paul soru sormuyor.</div><div class=\"kurss-example\">Er kommt nicht. — O gelmiyor.</div><div class=\"kurss-example\">Sie singen nicht. — Onlar şarkı söylemiyor.</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>2. dersten cümleler</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Spielst du? — Oynuyor musun?</div><div class=\"kurss-example\">Nein, ich spiele nicht, ich arbeite. — Hayır, oynamıyorum, çalışıyorum.</div><div class=\"kurss-example\">Paul fragt nicht, er arbeitet. — Paul soru sormuyor, o çalışıyor.</div><div class=\"kurss-example\">Arbeitest du? — Çalışıyor musun?</div><div class=\"kurss-example\">Nein, ich arbeite nicht, ich singe. — Hayır, çalışmıyorum, şarkı söylüyorum.</div><div class=\"kurss-example\">Was tut Paul? — Paul ne yapıyor?</div><div class=\"kurss-example\">Er spielt. — O oynuyor.</div><div class=\"kurss-example\">Was tut Marie? — Marie ne yapıyor?</div><div class=\"kurss-example\">Sie singt. — O şarkı söylüyor.</div><div class=\"kurss-example\">Paul spielt, aber Marie singt. — Paul oynuyor, ama Marie şarkı söylüyor.</div><div class=\"kurss-example\">Singt ihr? — Şarkı söylüyor musunuz?</div><div class=\"kurss-example\">Nein, wir singen nicht, wir arbeiten. — Hayır, şarkı söylemiyoruz, çalışıyoruz.</div><div class=\"kurss-example\">Was tun Paul und Marie? — Paul ve Marie ne yapıyor?</div><div class=\"kurss-example\">Sie fragen. — Onlar soru soruyor.</div><div class=\"kurss-example\">Sie antworten nicht. — Onlar cevap vermiyor.</div><div class=\"kurss-example\">Wer arbeitet? — Kim çalışıyor?</div><div class=\"kurss-example\">Wir arbeiten. — Biz çalışıyoruz.</div><div class=\"kurss-example\">Wir rechnen und zeichnen. — Hesap yapıyoruz ve resim çiziyoruz.</div><div class=\"kurss-example\">Sie kommen, sie fragen, sie antworten, sie arbeiten, sie spielen, sie singen, sie gehen. — Onlar geliyor, soruyor, cevap veriyor, çalışıyor, oynuyor, şarkı söylüyor ve gidiyor.</div></div>\n            </section>",
  "kurssLesson2": "            <h3>Ders 2</h3>\n            <p class=\"kurss-lesson-intro\">İkinci ders: diyaloglar, kelimeler, telaffuz, dilbilgisi ve çeviri.</p>\n            <details class=\"lesson1-accordion\" open>\n              <summary><span class=\"lesson1-number lesson1-number-red\">1.</span><span>Diyaloglar / cümleler</span><span class=\"lesson1-chevron\">⌃</span></summary>\n              <div class=\"lesson1-content\">\n                <div class=\"lesson1-card-grid\">\n                  <div class=\"kurss-example\">Spielst du?<br>Nein, ich spiele nicht, ich arbeite.</div>\n                  <div class=\"kurss-example\">Paul fragt nicht, er arbeitet.</div>\n                  <div class=\"kurss-example\">Arbeitest du?<br>Nein, ich arbeite nicht, ich singe.</div>\n                  <div class=\"kurss-example\">Was tut Paul?<br>Er spielt.</div>\n                  <div class=\"kurss-example\">Was tut Marie?<br>Sie singt.</div>\n                  <div class=\"kurss-example\">Paul spielt, aber Marie singt.</div>\n                  <div class=\"kurss-example\">Singt ihr?<br>Nein, wir singen nicht, wir arbeiten.</div>\n                  <div class=\"kurss-example\">Was tun Paul und Marie?<br>Sie fragen.<br>Sie antworten nicht.</div>\n                  <div class=\"kurss-example\">Wer arbeitet?<br>Wir arbeiten.<br>Wir rechnen und zeichnen.</div>\n                  <div class=\"kurss-example\">Sie kommen, sie fragen, sie antworten, sie arbeiten, sie spielen, sie singen, sie gehen.</div>\n                </div>\n              </div>\n            </details>\n            <details class=\"lesson1-accordion\">\n              <summary><span class=\"lesson1-number lesson1-number-green\">2.</span><span>Kelimeler</span><span class=\"lesson1-chevron\">⌄</span></summary>\n              <div class=\"lesson1-content\">\n                <div class=\"lesson1-card-grid\">\n                  <div class=\"kurss-example\">spielen — oynamak; çalmak</div>\n                  <div class=\"kurss-example\">nein — hayır</div>\n                  <div class=\"kurss-example\">nicht — değil</div>\n                  <div class=\"kurss-example\">arbeiten — çalışmak</div>\n                  <div class=\"kurss-example\">fragen — sormak</div>\n                  <div class=\"kurss-example\">was tut er? — o ne yapıyor?</div>\n                  <div class=\"kurss-example\">was tun sie? — onlar ne yapıyor?</div>\n                  <div class=\"kurss-example\">aber — ama</div>\n                  <div class=\"kurss-example\">antworten — cevap vermek</div>\n                  <div class=\"kurss-example\">rechnen — hesap yapmak</div>\n                  <div class=\"kurss-example\">zeichnen — resim çizmek</div>\n                  <div class=\"kurss-example\">Marie — Meryem</div>\n                </div>\n              </div>\n            </details>\n                        <details class=\"lesson1-accordion\">\n              <summary><span class=\"lesson1-number lesson1-number-purple\">3.</span><span>Telaffuz</span><span class=\"lesson1-chevron\">⌄</span></summary>\n              <div class=\"lesson1-content\">\n                <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ich, nicht, rechnen, zeichnen kelimelerinde ch sesi yumuşak okunur; aşağı yukarı Türkçedeki ihtiyaç, ihtimal kelimelerinde i'den sonra gelen h sesi gibi.</div><div class=\"kurss-example\">arbeiten, zeichnen kelimelerinde ei çift ünlüsü aşağı yukarı Türkçedeki ay gibi okunur.</div><div class=\"kurss-example\">sp ünsüz grubu şp gibi okunur: spielen (şpiilen).</div><div class=\"kurss-example\">tun fiilinde u bütün şahıslarda uzun okunur.</div></div>\n              </div>\n            </details>\n<details class=\"lesson1-accordion\">\n              <summary><span class=\"lesson1-number lesson1-number-blue\">4.</span><span>Dilbilgisi</span><span class=\"lesson1-chevron\">⌄</span></summary>\n              <div class=\"lesson1-content lesson1-grammar-content\">\n                <section class=\"lesson1-block\">\n                  <h4 class=\"lesson1-grammar-header\"><span>1</span>e'li ekler</h4>\n                  <div class=\"lesson1-grammar-note\">Fiil gövdesi t, d, chn ile bitiyorsa, çekimde -st ve -t eklerinden önce bir e gelir.</div>\n                  <h5 class=\"lesson2-subtitle\">arbeiten</h5>\n                  <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ich arbeite</div><div class=\"kurss-example\">du arbeitest</div><div class=\"kurss-example\">er arbeitet</div><div class=\"kurss-example\">sie arbeitet</div><div class=\"kurss-example\">wir arbeiten</div><div class=\"kurss-example\">ihr arbeitet</div><div class=\"kurss-example\">sie arbeiten</div></div>\n                  <h5 class=\"lesson2-subtitle\">rechnen</h5>\n                  <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ich rechne</div><div class=\"kurss-example\">du rechnest</div><div class=\"kurss-example\">er rechnet</div><div class=\"kurss-example\">sie rechnet</div><div class=\"kurss-example\">wir rechnen</div><div class=\"kurss-example\">ihr rechnet</div><div class=\"kurss-example\">sie rechnen</div></div>\n                  <h5 class=\"lesson2-subtitle\">tun</h5>\n                  <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ich tue</div><div class=\"kurss-example\">du tust</div><div class=\"kurss-example\">er tut</div><div class=\"kurss-example\">sie tut</div><div class=\"kurss-example\">wir tun</div><div class=\"kurss-example\">ihr tut</div><div class=\"kurss-example\">sie tun</div></div>\n                </section>\n                <section class=\"lesson1-block\">\n                  <h4 class=\"lesson1-grammar-header\"><span>2</span>Soru kelimesi</h4>\n                  <div class=\"lesson1-grammar-note\">Soru kelimesiyle başlayan soru cümlelerinde, örneğin: ne? kim? hangi? neden? niçin? vb., fiil hemen soru kelimesinden sonra gelir.</div>\n                  <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Was tust du? — Sen ne yapıyorsun?</div><div class=\"kurss-example\">Was tut er? — O (erkek) ne yapıyor?</div><div class=\"kurss-example\">Was tut sie? — O (kadın) ne yapıyor?</div><div class=\"kurss-example\">Was tun sie? — Onlar ne yapıyor?</div></div>\n                </section>\n                <section class=\"lesson1-block\">\n                  <h4 class=\"lesson1-grammar-header\"><span>3</span>nicht ile olumsuzluk</h4>\n                  <div class=\"lesson1-grammar-note\">Olumsuzluk sözcüğü nicht fiile ilişkinse, fiilden sonra gelir.</div>\n                  <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Er kommt nicht. — O gelmiyor.</div><div class=\"kurss-example\">Sie singen nicht. — Onlar şarkı söylemiyor.</div></div>\n                </section>\n              </div>\n            </details>\n                                    <details class=\"lesson1-accordion\">\n              <summary><span class=\"lesson1-number lesson1-number-orange\">5.</span><span>Çevir</span><span class=\"lesson1-chevron\">⌄</span></summary>\n              <div class=\"lesson1-content\">\n                <div class=\"lesson1-training-wrap\">\n                  <button class=\"lesson1-training-flashcard\" type=\"button\" data-lesson2-training-card data-training-index=\"0\" data-showing-back=\"false\" aria-label=\"Ders 2 çeviri kartı\">\n                    <span class=\"lesson1-training-progress\">Ders 2 · Çevir: 1 / 15</span>\n                    <span class=\"lesson1-training-text\">Kim soruyor?</span>\n                  </button>\n                  <p class=\"lesson1-training-hint\">Almanca çevirisini görmek için karta tıkla. Cevaptan sonra bir sonraki tıklama sonraki kartı gösterir.</p>\n                </div>\n              </div>\n            </details>",
  "kurssLesson6": "\n    <h3>Ders 6</h3>\n    <p class=\"kurss-lesson-intro\">Sayılar, çoğul, umlautlar ve isimlerin çoğul biçimleri.</p>\n\n    <details class=\"lesson1-accordion\" open>\n      <summary><span class=\"lesson1-number lesson1-number-red\">1.</span><span>Diyaloglar / cümleler</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Hier liegt ein Bleistift.</div><div class=\"kurss-example\">Dort liegen einige Messer.</div><div class=\"kurss-example\">Edgar nimmt ein Messer, zwei Messer, drei Messer.</div><div class=\"kurss-example\">Er legt die Messer wieder hin.</div><div class=\"kurss-example\">Alle Messer sind scharf.</div><div class=\"kurss-example\">Dann nimmt er wieder ein Messer.</div><div class=\"kurss-example\">Er macht das Messer auf.</div><div class=\"kurss-example\">Er nimmt den Bleistift.</div><div class=\"kurss-example\">Er spitzt den Bleistift an.</div><div class=\"kurss-example\">Er legt das Messer hin.</div><div class=\"kurss-example\">Er setzt sich und zeichnet.</div><div class=\"kurss-example\">Was zeichnet er? Er zeichnet einen Schlüssel.</div><div class=\"kurss-example\">Gertrud zeichnet ein Fenster und eine Tafel.</div><div class=\"kurss-example\">Anna zeichnet einen Garten.</div><div class=\"kurss-example\">Hier liegen vier Löffel.</div><div class=\"kurss-example\">Dort liegen fünf Nadeln.</div><div class=\"kurss-example\">Gertrud kommt und zählt die Löffel: das ist ein Löffel; das sind zwei, drei, vier Löffel.</div><div class=\"kurss-example\">Anna zählt die Nadeln: das ist eine Nadel; das sind zwei, drei, vier, fünf Nadeln.</div><div class=\"kurss-example\">Wieviel Nadeln sind hier?</div><div class=\"kurss-example\">Hier ist eine Nadel.</div><div class=\"kurss-example\">Dort sind zwei, drei, vier Nadeln.</div><div class=\"kurss-example\">Fünf Schlüssel sind hier.</div><div class=\"kurss-example\">Sechs Löffel sind dort.</div><div class=\"kurss-example\">Was ist das?</div><div class=\"kurss-example\">Das ist ein Hammer. Das sind fünf Hämmer.</div><div class=\"kurss-example\">Das ist ein Deckel. Das sind sechs Deckel.</div><div class=\"kurss-example\">Das ist ein Eimer. Das sind sieben Eimer.</div><div class=\"kurss-example\">Das ist ein Teller. Das sind acht Teller.</div><div class=\"kurss-example\">Das ist ein Wagen. Das sind neun Wagen.</div><div class=\"kurss-example\">Das ist ein Schlitten. Das sind zehn Schlitten.</div><div class=\"kurss-example\">Wie sind die Dinge?</div><div class=\"kurss-example\">Der Hammer ist klein. Die Hämmer sind klein.</div><div class=\"kurss-example\">Der Deckel ist groß. Die Deckel sind groß.</div><div class=\"kurss-example\">Der Eimer ist voll. Die Eimer sind voll.</div><div class=\"kurss-example\">Der Teller ist leer. Die Teller sind leer.</div><div class=\"kurss-example\">Der Wagen ist schwer. Die Wagen sind schwer.</div><div class=\"kurss-example\">Der Schlitten ist leicht. Die Schlitten sind leicht.</div></div></div>\n    </details>\n\n    <details class=\"lesson1-accordion\">\n      <summary><span class=\"lesson1-number lesson1-number-green\">2.</span><span>Kelimeler</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">liegt — bulunuyor, var, yatıyor</div><div class=\"kurss-example\">der Bleistift (blayştift) — kurşun kalem</div><div class=\"kurss-example\">einige (aynige) — birkaç</div><div class=\"kurss-example\">hinlegen — bırakmak, koymak</div><div class=\"kurss-example\">legt hin — bırakıyor</div><div class=\"kurss-example\">wieder (viider) — yine, tekrar</div><div class=\"kurss-example\">aufmachen — açmak</div><div class=\"kurss-example\">er macht auf — o açıyor</div><div class=\"kurss-example\">anspitzen (anşpitsen) — sivriltmek, kalem açmak</div><div class=\"kurss-example\">er spitzt an — o kalemi açıyor</div><div class=\"kurss-example\">sich setzen — oturmak</div><div class=\"kurss-example\">setzt sich — oturuyor</div><div class=\"kurss-example\">der Schlüssel (şlüssel) — anahtar</div><div class=\"kurss-example\">das Fenster (fenster) — pencere</div><div class=\"kurss-example\">die Tafel (dii taafel) — yazı tahtası</div><div class=\"kurss-example\">der Garten — bahçe</div><div class=\"kurss-example\">der Löffel — kaşık</div><div class=\"kurss-example\">zählen (tseelen) — saymak</div><div class=\"kurss-example\">die Nadel — iğne</div><div class=\"kurss-example\">was ist das — bu ne?</div><div class=\"kurss-example\">der Hammer — çekiç</div><div class=\"kurss-example\">die Hämmer — çekiçler</div><div class=\"kurss-example\">der Deckel (deer dekel) — kapak</div><div class=\"kurss-example\">der Teller — tabak</div><div class=\"kurss-example\">der Wagen — araba</div><div class=\"kurss-example\">der Schlitten — kızak</div><div class=\"kurss-example\">das Ding — şey, eşya</div><div class=\"kurss-example\">die Dinge — şeyler, eşyalar</div><div class=\"kurss-example\">wie sind die Dinge? — eşyalar nasıl?</div><div class=\"kurss-example\">voll (fol) — dolu</div><div class=\"kurss-example\">leer (leer) — boş</div><div class=\"kurss-example\">schwer (şveer) — ağır, zor</div><div class=\"kurss-example\">leicht — hafif</div><div class=\"kurss-example\">der Eimer — kova</div><div class=\"kurss-example\">wieviel (viifiil) — kaç, ne kadar</div><div class=\"kurss-example\">wieviel Nadeln — kaç iğne</div><div class=\"kurss-example\">hier (hiir) — burada</div><div class=\"kurss-example\">dort — orada</div></div></div>\n    </details>\n\n    <details class=\"lesson1-accordion\">\n      <summary><span class=\"lesson1-number lesson1-number-purple\">3.</span><span>Telaffuz</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ä, a ünlüsünün umlautlu biçimidir ve kısa ya da uzun kapalı bir e gibi okunur.</div><div class=\"kurss-example\">Örnekler: das Mädchen (meethen), die Bänke (dii benke), der Vater (deer faater), die Väter (dii feeter).</div><div class=\"kurss-example\">ü, u ünlüsünün umlautlu biçimidir ve Türkçedeki ü gibi okunur: dudaklar iyice yuvarlatılır ve yuvarlak dudaklarla i söylenmeye çalışılır.</div><div class=\"kurss-example\">Örnekler: fünf, der Schlüssel (şlüssel).</div><div class=\"kurss-example\">ö, Türkçedeki ö gibi, dudaklar yuvarlatılarak e söylenmeye çalışılır: der Löffel.</div><div class=\"kurss-example\">Çift yazılan ünlü uzun ünlüyü gösterir: leer (leer).</div><div class=\"kurss-example\">eu çift ünlüsü oy gibi okunur: neun (noyn).</div></div></div>\n    </details>\n\n    <details class=\"lesson1-accordion\">\n      <summary><span class=\"lesson1-number lesson1-number-blue\">4.</span><span>Dilbilgisi</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content lesson1-grammar-content\">\n        <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\">Dilbilgisi ve açıklamalar</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Birleşik fiilin vurgulu ön eki şimdiki zamanda fiilden ayrılır ve cümlenin sonunda yer alır.</div><div class=\"kurss-example\">Örnekler: hinlegen — er legt hin; aufmachen — er macht auf; anspitzen — er spitzt an.</div><div class=\"kurss-example\">“Bir” sayısının, bir isimle kullanıldığında üç cinste de biçimi vardır: erilde ein, dişilde eine, nötrde ein.</div><div class=\"kurss-example\">Örnekler: ein Schüler — bir öğrenci; eine Schülerin — bir kız öğrenci; ein Kind — bir çocuk.</div><div class=\"kurss-example\">Sayılar: eins, zwei, drei, vier (fiir), fünf, sechs (zeks), sieben (ziiben), acht, neun (noyn), zehn (tseen).</div><div class=\"kurss-example\">Almancada ekfiilin tekil ve çoğul biçimi vardır: der Schüler ist klein; die Schüler sind klein.</div><div class=\"kurss-example\">Türkçede işaret zamiri çoğulda değişir, bu ve bunlar gibi; Almancada ise tek bir biçim kullanılır: das.</div><div class=\"kurss-example\">Örnekler: bu bir çekiç — das ist ein Hammer; bu bir iğne — das ist eine Nadel; bunlar çekiç — das sind Hämmer; bunlar iğne — das sind Nadeln.</div><div class=\"kurss-example\">Der Wagen — araba ve der Schlitten — kızak Almancada hem tekil hem de çoğul olarak kullanılır.</div><div class=\"kurss-example\">-er, -el, -en ile biten eril ve nötr isimler çoğulda çoğu zaman ek almaz.</div><div class=\"kurss-example\">Örnekler: der Hammer — die Hämmer; der Garten — die Gärten; das Fenster — die Fenster; das Messer — die Messer.</div><div class=\"kurss-example\">-el, -er ile biten dişil isimler çoğulda -n alır.</div><div class=\"kurss-example\">Örnekler: die Nadel — die Nadeln; die Feder — die Federn.</div><div class=\"kurss-example\">İstisnalar: die Mutter (anne) — die Mütter (anneler); die Tochter (kız evlat) — die Töchter (kız evlatlar).</div><div class=\"kurss-example\">Belirsiz artikelin çoğulu yoktur: das ist ein Wagen — das sind Wagen; das ist eine Nadel — das sind Nadeln.</div><div class=\"kurss-example\">Düz cümlede yüklem olan fiil ikinci sırada bulunur: er legt den Schlüssel hin; dann legt er den Schlüssel hin.</div></div></section>\n      </div>\n    </details>\n\n    <details class=\"lesson1-accordion\">\n      <summary><span class=\"lesson1-number lesson1-number-orange\">5.</span><span>Çevir</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content\"><div class=\"lesson1-training-wrap\"><button class=\"lesson1-training-flashcard\" type=\"button\" data-lesson6-training-card data-training-index=\"0\" data-showing-back=\"false\" aria-label=\"Ders 6 çeviri kartı\"><span class=\"lesson1-training-progress\">Ders 6 · Çevir: 1 / 21</span><span class=\"lesson1-training-text\">Paul bir kurşun kalem alıyor ve resim çiziyor.</span></button><p class=\"lesson1-training-hint\">Almanca çevirisini görmek için karta tıkla. Cevaptan sonra bir sonraki tıklama sonraki kartı gösterir.</p></div></div>\n    </details>\n  ",
  "kurssLesson5": "\n    <h3>Ders 5</h3>\n    <p class=\"kurss-lesson-intro\">Wen?, akuzatif, sitzen, fragen ve -in eki.</p>\n\n    <details class=\"lesson1-accordion\" open>\n      <summary><span class=\"lesson1-number lesson1-number-red\">1.</span><span>Diyaloglar / cümleler</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\">\n        <div class=\"kurss-example\">Wer sitzt und fragt? Der Lehrer sitzt und fragt.</div>\n        <div class=\"kurss-example\">Wer steht und antwortet? Der Schüler steht und antwortet.</div>\n        <div class=\"kurss-example\">Wie antwortet der Schüler? Der Schüler antwortet gut.</div>\n        <div class=\"kurss-example\">Wen lobt der Lehrer? Der Lehrer lobt den Schüler.</div>\n        <div class=\"kurss-example\">Wie ist der Schüler? Der Schüler ist klein.</div>\n        <div class=\"kurss-example\">Ist der Schüler klein oder groß? Er ist klein.</div>\n        <div class=\"kurss-example\">Wen fragt die Lehrerin? Die Lehrerin fragt die Schülerin.</div>\n        <div class=\"kurss-example\">Wie antwortet die Schülerin? Die Schülerin antwortet schlecht.</div>\n        <div class=\"kurss-example\">Was tut die Lehrerin? Sie tadelt die Schülerin.</div>\n        <div class=\"kurss-example\">Die Schülerin ist nicht klein, sie ist groß.</div>\n        <div class=\"kurss-example\">Ein Kind spielt. Das Kind ist artig.</div>\n        <div class=\"kurss-example\">Die Mutter liebt das Kind. Der Vater lobt das Kind.</div>\n      </div></div>\n    </details>\n\n    <details class=\"lesson1-accordion\">\n      <summary><span class=\"lesson1-number lesson1-number-green\">2.</span><span>Kelimeler</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\">\n        <div class=\"kurss-example\">sitzen (zitsen) — oturmak</div>\n        <div class=\"kurss-example\">fragen (fraagen) — sormak</div>\n        <div class=\"kurss-example\">der Lehrer (deer leerer) — öğretmen</div>\n        <div class=\"kurss-example\">gut (guut) — iyi</div>\n        <div class=\"kurss-example\">wen (veen) — kimi</div>\n        <div class=\"kurss-example\">loben — övmek</div>\n        <div class=\"kurss-example\">der Schüler (şüüler) — öğrenci</div>\n        <div class=\"kurss-example\">klein — küçük</div>\n        <div class=\"kurss-example\">groß (groos) — büyük</div>\n        <div class=\"kurss-example\">die Lehrerin — kadın öğretmen</div>\n        <div class=\"kurss-example\">die Schülerin — kız öğrenci</div>\n        <div class=\"kurss-example\">schlecht (şleht) — kötü</div>\n        <div class=\"kurss-example\">tadeln — azarlamak, kınamak</div>\n        <div class=\"kurss-example\">oder (ooder) — veya</div>\n        <div class=\"kurss-example\">das Kind (kint) — çocuk</div>\n        <div class=\"kurss-example\">artig (aartih) — uslu</div>\n        <div class=\"kurss-example\">die Mutter — anne</div>\n        <div class=\"kurss-example\">lieben (liiben) — sevmek</div>\n        <div class=\"kurss-example\">der Vater (faater) — baba</div>\n      </div></div>\n    </details>\n\n        <details class=\"lesson1-accordion\">\n      <summary><span class=\"lesson1-number lesson1-number-purple\">3.</span><span>Telaffuz</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\">\n        <div class=\"kurss-example\">tz çift z sesidir ve Almanca z gibi, yani ts okunur: sitzen (zitsen).</div>\n        <div class=\"kurss-example\">Almanca kelimelerde v, f gibi okunur: der Vater (faater).</div>\n        <div class=\"kurss-example\">ß'ye eszett denir ve Türkçedeki s gibi okunur: groß (groos), weiß (vays).</div>\n      </div></div>\n    </details>\n\n<details class=\"lesson1-accordion\">\n      <summary><span class=\"lesson1-number lesson1-number-blue\">4.</span><span>Dilbilgisi</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content lesson1-grammar-content\">\n        <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\">Nominatif ve akuzatif</h4><div class=\"lesson1-grammar-note\">Türkçede yalın hâl kim? / ne? sorusuna, belirtme hâli ise kimi? / neyi? sorusuna cevap verir.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Almancada nominatifte soru, kişiler için wer?, nesneler için was? şeklindedir.</div><div class=\"kurss-example\">Akuzatifte soru, kişiler için wen?, nesneler için was? şeklindedir.</div></div></section>\n        <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\">Akuzatifte artikellerin değişimi</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Nominativ: der Vater, die Mutter, das Kind.</div><div class=\"kurss-example\">Akkusativ: den Vater, die Mutter, das Kind.</div><div class=\"kurss-example\">Nominativ: der Federhalter, die Feder, das Messer.</div><div class=\"kurss-example\">Akkusativ: den Federhalter, die Feder, das Messer.</div></div></section>\n        <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\">sitzen</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ich sitze</div><div class=\"kurss-example\">du sitzt</div><div class=\"kurss-example\">er/sie/es sitzt</div><div class=\"kurss-example\">wir sitzen</div><div class=\"kurss-example\">ihr sitzt</div><div class=\"kurss-example\">sie sitzen</div></div></section>\n        <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\">fragen + akuzatif</h4><div class=\"lesson1-grammar-note\">Almancada fragen fiili akuzatif ister.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Wen fragt der Lehrer?</div><div class=\"kurss-example\">Der Lehrer fragt den Schüler.</div></div></section>\n        <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\">-in eki</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Pek çok dişil kelime -in ekiyle türetilir.</div><div class=\"kurss-example\">die Lehrerin</div><div class=\"kurss-example\">die Schülerin</div></div></section>\n        <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\">Fiilin yeri</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Düz cümlede fiil ikinci sırada bulunur.</div><div class=\"kurss-example\">Dann geht das Mädchen hinaus und arbeitet.</div><div class=\"kurss-example\">Das Mädchen geht dann hinaus und arbeitet.</div></div></section>\n      </div>\n    </details>\n\n    <details class=\"lesson1-accordion\">\n      <summary><span class=\"lesson1-number lesson1-number-orange\">5.</span><span>Çevir</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content\"><div class=\"lesson1-training-wrap\"><button class=\"lesson1-training-flashcard\" type=\"button\" data-lesson5-training-card data-training-index=\"0\" data-showing-back=\"false\" aria-label=\"Ders 5 çeviri kartı\"><span class=\"lesson1-training-progress\">Ders 5 · Çevir: 1 / 16</span><span class=\"lesson1-training-text\">Baba kimi seviyor?</span></button><p class=\"lesson1-training-hint\">Almanca çevirisini görmek için karta tıkla. Cevaptan sonra bir sonraki tıklama sonraki kartı gösterir.</p></div></div>\n    </details>\n  ",
  "kurssLesson4": "            <h3>Ders 4</h3>\n            <p class=\"kurss-lesson-intro\">Akuzatif, nehmen, hinlegen, hinausgehen ve sıfatlar.</p>\n            <details class=\"lesson1-accordion\" open>\n              <summary><span class=\"lesson1-number lesson1-number-red\">1.</span><span>Diyaloglar / cümleler</span><span class=\"lesson1-chevron\">⌃</span></summary>\n              <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Paul kommt und nimmt einen Federhalter.</div><div class=\"kurss-example\">Er zeigt den Federhalter.</div><div class=\"kurss-example\">Er fragt: „Wie ist der Federhalter?“</div><div class=\"kurss-example\">Olga antwortet: „Der Federhalter ist schwarz.“</div><div class=\"kurss-example\">Ist der Federhalter weiß? Nein, der Federhalter ist nicht weiß, er ist schwarz.</div><div class=\"kurss-example\">Marie kommt und nimmt eine Feder.</div><div class=\"kurss-example\">Sie fragt: „Wie ist die Feder?“</div><div class=\"kurss-example\">Olga antwortet: „Die Feder ist spitz.“</div><div class=\"kurss-example\">Ist die Feder stumpf? Nein, die Feder ist nicht stumpf, sie ist spitz.</div><div class=\"kurss-example\">Was legt das Mädchen hin? Es legt die Feder hin.</div><div class=\"kurss-example\">Was nimmst du? Ich nehme ein Messer.</div><div class=\"kurss-example\">Wie ist das Messer? Das Messer ist scharf.</div><div class=\"kurss-example\">Ist das Messer stumpf? Nein, es ist nicht stumpf, es ist scharf.</div><div class=\"kurss-example\">Was legst du hin? Ich lege das Messer, die Feder und den Federhalter hin.</div><div class=\"kurss-example\">Dann gehe ich hinaus und arbeite.</div></div></div>\n            </details>\n            <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-green\">2.</span><span>Kelimeler</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">nehmen (neemen) — almak</div><div class=\"kurss-example\">er nimmt (nimt) — o alıyor</div><div class=\"kurss-example\">der Federhalter (deer feederhalter) — kalem sapı</div><div class=\"kurss-example\">einen Federhalter — bir kalem sapı</div><div class=\"kurss-example\">zeigen — göstermek</div><div class=\"kurss-example\">schwarz (şvarts) — siyah</div><div class=\"kurss-example\">weiß (vays) — beyaz</div><div class=\"kurss-example\">die Feder (dii feeder) — kalem ucu</div><div class=\"kurss-example\">eine Feder — bir kalem ucu</div><div class=\"kurss-example\">spitz (şpits) — sivri</div><div class=\"kurss-example\">hinlegen — bırakmak, koymak</div><div class=\"kurss-example\">legt hin — bırakıyor</div><div class=\"kurss-example\">das Mädchen (meethen) — kız</div><div class=\"kurss-example\">das Messer — bıçak</div><div class=\"kurss-example\">ein Messer — bir bıçak</div><div class=\"kurss-example\">scharf — keskin</div><div class=\"kurss-example\">stumpf (ştumpf) — kör, keskin olmayan</div><div class=\"kurss-example\">dann — sonra</div><div class=\"kurss-example\">hinaus — dışarı</div><div class=\"kurss-example\">hinausgehen — dışarı çıkmak</div></div></div></details>\n                        <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-purple\">3.</span><span>Telaffuz</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">-en, -er, -el ekleri vurgusuzdur, bu yüzden bu eklerdeki e zayıf duyulur: kommen, nehmen, der Federhalter.</div><div class=\"kurss-example\">Almancada h hem bir ses hem de önceki ünlünün uzatma işareti olabilir.</div><div class=\"kurss-example\">h uzatma işaretiyse ses olarak okunmaz: nehmen (neemen).</div><div class=\"kurss-example\">Ünlüden sonra yalnızca bir ünsüz geliyorsa ünlü uzun okunur: die (dii) Feder (feeder), den (deen).</div></div></div></details>\n<details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-blue\">4.</span><span>Dilbilgisi</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content lesson1-grammar-content\"><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>1</span>Akuzatif</h4><div class=\"lesson1-grammar-note\">Dişil ve nötr cinste akuzatif nominatifle aynıdır. Yalnızca eril cins değişir.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Nominativ: der Federhalter, die Feder, das Messer.</div><div class=\"kurss-example\">Akkusativ: den Federhalter, die Feder, das Messer.</div><div class=\"kurss-example\">Nominativ: ein Federhalter, eine Feder, ein Messer.</div><div class=\"kurss-example\">Akkusativ: einen Federhalter, eine Feder, ein Messer.</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>2</span>nehmen</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ich nehme</div><div class=\"kurss-example\">du nimmst</div><div class=\"kurss-example\">er/sie nimmt</div><div class=\"kurss-example\">wir nehmen</div><div class=\"kurss-example\">ihr nehmt</div><div class=\"kurss-example\">sie nehmen</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>3</span>Zamirler</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">er — eril</div><div class=\"kurss-example\">sie — dişil</div><div class=\"kurss-example\">es — nötr</div><div class=\"kurss-example\">çoğulda — sie</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>4</span>Ayrılabilen fiiller</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">hinlegen → ich lege das Messer hin</div><div class=\"kurss-example\">hinausgehen → Marie geht hinaus</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>5</span>Sıfatlar</h4><div class=\"lesson1-grammar-note\">Sıfat cümlede yüklem ise ne cinse ne de sayıya göre değişir.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">der Federhalter ist klein</div><div class=\"kurss-example\">die Feder ist klein</div><div class=\"kurss-example\">das Messer ist klein</div><div class=\"kurss-example\">die Messer sind klein</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>6</span>nicht ile olumsuzluk</h4><div class=\"lesson1-grammar-note\">nicht bir sıfatı olumsuz yapıyorsa, olumsuzlanan kelimenin önünde durur.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">der Federhalter ist nicht weiß</div><div class=\"kurss-example\">das Messer ist nicht scharf</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>7</span>-chen / -lein</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">-chen ve -lein ekli isimler nötr cinstendir: das Mädchen.</div></div></section></div></details>\n            <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-orange\">5.</span><span>Çevir</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-training-wrap\"><button class=\"lesson1-training-flashcard\" type=\"button\" data-lesson4-training-card data-training-index=\"0\" data-showing-back=\"false\" aria-label=\"Ders 4 çeviri kartı\"><span class=\"lesson1-training-progress\">Ders 4 · Çevir: 1 / 16</span><span class=\"lesson1-training-text\">Kız bir kalem sapı alıyor.</span></button><p class=\"lesson1-training-hint\">Almanca çevirisini görmek için karta tıkla. Cevaptan sonra bir sonraki tıklama sonraki kartı gösterir.</p></div></div></details>",
  "kurssLesson3": "            <h3>Ders 3</h3>\n            <p class=\"kurss-lesson-intro\">Üçüncü ders: diyaloglar, kelimeler, telaffuz, dilbilgisi ve çeviri.</p>\n            <details class=\"lesson1-accordion\" open>\n              <summary><span class=\"lesson1-number lesson1-number-red\">1.</span><span>Diyaloglar / cümleler</span><span class=\"lesson1-chevron\">⌃</span></summary>\n              <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Wer rechnet und zeichnet?<br>Wir rechnen und zeichnen.</div><div class=\"kurss-example\">Wer kommt?<br>Paul und Anna kommen.</div><div class=\"kurss-example\">Was steht hier?<br>Hier steht ein Tisch.</div><div class=\"kurss-example\">Was steht dort?<br>Dort steht eine Bank.</div><div class=\"kurss-example\">Was liegt hier?<br>Hier liegt ein Buch.</div><div class=\"kurss-example\">Was liegt dort?<br>Dort liegt ein Heft.</div><div class=\"kurss-example\">Was hängt hier?<br>Hier hängt ein Bild.</div><div class=\"kurss-example\">Was hängt dort?<br>Dort hängt eine Tafel.</div><div class=\"kurss-example\">Wie ist das Buch?<br>Das Buch ist dick.</div><div class=\"kurss-example\">Wie ist das Heft?<br>Das Heft ist dünn.</div><div class=\"kurss-example\">Wie ist die Bank?<br>Die Bank ist niedrig.</div><div class=\"kurss-example\">Wie ist der Tisch?<br>Der Tisch ist hoch.</div></div></div>\n            </details>\n            <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-green\">2.</span><span>Kelimeler</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">wer — kim</div><div class=\"kurss-example\">was — ne</div><div class=\"kurss-example\">hier — burada</div><div class=\"kurss-example\">dort — orada</div><div class=\"kurss-example\">der Tisch — masa</div><div class=\"kurss-example\">ein Tisch — bir masa</div><div class=\"kurss-example\">die Bank — bank, sıra</div><div class=\"kurss-example\">eine Bank — bir bank</div><div class=\"kurss-example\">liegen — yatmak, yatay durmak</div><div class=\"kurss-example\">liegt hier ein Buch? — burada bir kitap var mı / duruyor mu?</div><div class=\"kurss-example\">das Buch — kitap</div><div class=\"kurss-example\">ein Buch — bir kitap</div><div class=\"kurss-example\">hängen — asılı durmak</div><div class=\"kurss-example\">das Bild — resim</div><div class=\"kurss-example\">ein Bild — bir resim</div><div class=\"kurss-example\">die Tafel — yazı tahtası</div><div class=\"kurss-example\">eine Tafel — bir yazı tahtası</div><div class=\"kurss-example\">wie — nasıl</div><div class=\"kurss-example\">ist — -dır, -dir</div><div class=\"kurss-example\">dick — kalın, şişman</div><div class=\"kurss-example\">das Heft — defter</div><div class=\"kurss-example\">ein Heft — bir defter</div><div class=\"kurss-example\">dünn — ince, zayıf</div><div class=\"kurss-example\">niedrig — alçak</div><div class=\"kurss-example\">hoch — yüksek</div></div></div></details>\n                        <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-purple\">3.</span><span>Telaffuz</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Almancada uzun i sesi ie ile yazılır: liegen (liigen), hier (hiir), wie (vii).</div><div class=\"kurss-example\">ck çift k'dır: dick (dikk).</div><div class=\"kurss-example\">Sıfat ve zarflarda -ig eki hafif bir -ich gibi okunur: niedrig (niidrih).</div><div class=\"kurss-example\">-ig ekinden sonra e gelirse, yani -ige olursa, g net bir g sesi olarak okunur: niedrige (niidrige) Bänke.</div></div></div></details>\n<details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-blue\">4.</span><span>Dilbilgisi</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content lesson1-grammar-content\"><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>1</span>Özne</h4><div class=\"lesson1-grammar-note\">Almancada özne wer? / was? sorusuna cevap verir ve nominatif hâldedir.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">wer? ile kişiler sorulur.</div><div class=\"kurss-example\">was? ile nesneler sorulur.</div><div class=\"kurss-example\">Wer singt? — Sie singt.</div><div class=\"kurss-example\">Was liegt hier? — Hier liegt ein Buch.</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>2</span>Artikeller</h4><div class=\"lesson1-grammar-note\">Almancada isimlerin 3 cinsi vardır: eril, dişil ve nötr. İsimlerin önünde genellikle artikel denen küçük bir kelime bulunur. Bu kelime çevrilmez.</div><h5 class=\"lesson2-subtitle\">Belirli artikel</h5><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">eril — der</div><div class=\"kurss-example\">dişil — die</div><div class=\"kurss-example\">nötr — das</div><div class=\"kurss-example\">Çoğulda belirli artikel üç cins için de die'dir.</div><div class=\"kurss-example\">der Tisch — die Tische</div><div class=\"kurss-example\">die Bank — die Bänke</div><div class=\"kurss-example\">das Heft — die Hefte</div></div><h5 class=\"lesson2-subtitle\">Belirsiz artikel</h5><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">eril — ein</div><div class=\"kurss-example\">dişil — eine</div><div class=\"kurss-example\">nötr — ein</div><div class=\"kurss-example\">Belirsiz artikelin çoğulu yoktur.</div><div class=\"kurss-example\">ein Tisch — Tische</div><div class=\"kurss-example\">ein Heft — Hefte</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>3</span>Özel isimler</h4><div class=\"lesson1-grammar-note\">Özel isimlerin önünde artikel kullanılmaz.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Hans spielt, aber Marie singt.</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>4</span>Fiilin yeri</h4><div class=\"lesson1-grammar-note\">Düz cümlede fiil ikinci sırada bulunur.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Hier hängt eine Karte.</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>5</span>stehen / liegen / hängen</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Almancada dik duran nesneler için nesnenin “durduğu” söylenir:<br>der Tisch steht<br>die Bank steht</div><div class=\"kurss-example\">Yatay konumdaki nesneler için “yattıkları” söylenir:<br>das Buch liegt<br>das Heft liegt</div><div class=\"kurss-example\">Nesneler asılı da durabilir:<br>die Karte hängt<br>die Tafel hängt</div></div></section></div></details>\n            <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-orange\">5.</span><span>Çevir</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-training-wrap\"><button class=\"lesson1-training-flashcard\" type=\"button\" data-lesson3-training-card data-training-index=\"0\" data-showing-back=\"false\" aria-label=\"Ders 3 çeviri kartı\"><span class=\"lesson1-training-progress\">Ders 3 · Çevir: 1 / 22</span><span class=\"lesson1-training-text\">Hesap yapıyor musun?</span></button><p class=\"lesson1-training-hint\">Almanca çevirisini görmek için karta tıkla. Cevaptan sonra bir sonraki tıklama sonraki kartı gösterir.</p></div></div></details>",
  "kurssLesson7": "            <h3>Ders 7</h3>\n            <p class=\"kurss-lesson-intro\">Yedinci ders: emir kipi, hitap biçimi ve çoğul.</p>\n            <details class=\"lesson1-accordion\" open>\n              <summary><span class=\"lesson1-number lesson1-number-red\">1.</span><span>Diyaloglar / cümleler</span><span class=\"lesson1-chevron\">⌃</span></summary>\n              <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Hans, singe ein Lied! Was tust du? Ich singe ein Lied.</div><div class=\"kurss-example\">Hans und Olga, singt ein Lied! Was tut ihr? Wir singen ein Lied.</div><div class=\"kurss-example\">Fräulein Müller, singen Sie, bitte, ein Lied! Was tun Sie? Ich singe ein Lied.</div><div class=\"kurss-example\">Hans, zähle die Teller! Was tut Hans? Er zählt die Teller.</div><div class=\"kurss-example\">Hans und Olga, zählt die Teller! Was tun Hans und Olga? Sie zählen die Teller.</div><div class=\"kurss-example\">Fräulein Müller, zählen Sie, bitte, die Teller!</div><div class=\"kurss-example\">Hans, öffne das Fenster! Was tut Hans? Er öffnet das Fenster.</div><div class=\"kurss-example\">Hans und Olga, öffnet die Fenster! Was tun Hans und Olga? Sie öffnen die Fenster.</div><div class=\"kurss-example\">Fräulein Müller, öffnen Sie, bitte, alle Fenster!</div><div class=\"kurss-example\">Fräulein Müller öffnet alle Fenster.</div><div class=\"kurss-example\">Das ist der Spiegel. Das sind die Spiegel.</div><div class=\"kurss-example\">Das ist der Lappen. Das sind die Lappen.</div><div class=\"kurss-example\">Das ist der Spaten. Das sind die Spaten.</div><div class=\"kurss-example\">Das ist der Besen. Das sind die Besen.</div><div class=\"kurss-example\">Das ist die Schaufel. Das sind die Schaufeln.</div><div class=\"kurss-example\">Das ist die Schüssel. Das sind die Schüsseln.</div><div class=\"kurss-example\">Das ist das Zimmer. Das sind die Zimmer.</div><div class=\"kurss-example\">Das ist das Ufer. Das sind die Ufer.</div></div></div>\n            </details>\n            <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-green\">2.</span><span>Kelimeler</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">singen — şarkı söylemek</div><div class=\"kurss-example\">singe — şarkı söyle</div><div class=\"kurss-example\">singt — şarkı söyleyin</div><div class=\"kurss-example\">singen Sie — şarkı söyleyin (kibar hitap)</div><div class=\"kurss-example\">das Lied (das liit) — şarkı</div><div class=\"kurss-example\">Sie — Siz (kibar hitap)</div><div class=\"kurss-example\">zählen — saymak</div><div class=\"kurss-example\">das Fräulein (froylayn) — genç bayan, matmazel</div><div class=\"kurss-example\">der Müller — değirmenci</div><div class=\"kurss-example\">öffnen — açmak</div><div class=\"kurss-example\">das Fenster (fenster) — pencere</div><div class=\"kurss-example\">alle — hepsi, herkes</div><div class=\"kurss-example\">der Spiegel (şpiigel) — ayna</div><div class=\"kurss-example\">der Lappen — bez, paçavra</div><div class=\"kurss-example\">der Spaten — bel küreği</div><div class=\"kurss-example\">der Besen — süpürge</div><div class=\"kurss-example\">die Schaufel — kürek</div><div class=\"kurss-example\">die Schüssel — kâse</div><div class=\"kurss-example\">das Zimmer — oda</div><div class=\"kurss-example\">das Ufer (uufer) — kıyı</div></div></div></details>\n            <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-purple\">3.</span><span>Telaffuz</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">sp kelime veya hece başında şp gibi okunur: der Spiegel (deer şpiigel).</div><div class=\"kurss-example\">sch Türkçedeki ş gibi okunur: die Schaufel (dii şaufel), die Schüssel (dii şüssel).</div><div class=\"kurss-example\">äu çift ünlüsü Türkçedeki oy gibi okunur: das Fräulein (das froylayn).</div></div></div></details>\n            <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-blue\">4.</span><span>Dilbilgisi</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content lesson1-grammar-content\"><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>1</span>Emir kipi</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Tekil 2. şahıs emir kipi, fiilin tekil 2. şahıs biçiminden -st şahıs eki atılıp -e eki eklenerek oluşturulur.</div><div class=\"kurss-example\">Örnekler: antworte!, arbeite!, öffne!, zeichne!</div><div class=\"kurss-example\">Emir biçimi tek heceliyse -e eki çoğu zaman kullanılmaz: geh!, steh!, komm!, tu!, sing!, frag!</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>2</span>Çoğul emir</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Çoğul 2. şahıs emir biçimi, şimdiki zamanın çoğul 2. şahıs biçimiyle aynıdır, ancak zamirsiz kullanılır.</div><div class=\"kurss-example\">Örnekler: antwortet!, arbeitet!, öffnet!, zeichnet!, geht!, steht!, tut!</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>3</span>Sie ile hitap biçimi</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">“Siz” ile yapılan kibar hitap biçimi çoğul 3. şahsa benzer. Sie zamiri büyük harfle yazılır ve fiilden sonra gelir.</div><div class=\"kurss-example\">Örnekler: antworten Sie!, arbeiten Sie!, öffnen Sie!, zeichnen Sie!, gehen Sie!, stehen Sie!, tun Sie!</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>4</span>öffnen</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">öffnen fiilinde, telaffuzu kolaylaştırmak için tekil 2. ve 3. şahısta ve çoğul 2. şahısta gövde ile ek arasına bir e eklenir: du öffnest, er öffnet, ihr öffnet.</div></div></section></div></details>\n            <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-orange\">5.</span><span>Übung / Alıştırma</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-training-wrap\"><button class=\"lesson1-training-flashcard\" type=\"button\" data-lesson7-exercise-card data-training-index=\"0\" data-showing-back=\"false\" aria-label=\"Ders 7 alıştırma kartı\"><span class=\"lesson1-training-progress\">Ders 7 · Übung: 1 / 16</span><span class=\"lesson1-training-text\">fragen — sormak</span></button><p class=\"lesson1-training-hint\">Emir biçimlerini görmek için karta dokun.</p></div></div></details>",
  "kurssLesson1": "            <h3>Ders 1</h3>\n            <p class=\"kurss-lesson-intro\">Birinci ders: şimdiki zamanda fiiller, kelimeler, telaffuz, dilbilgisi ve çeviri.</p>\n            <details class=\"lesson1-accordion\" open>\n              <summary><span class=\"lesson1-number lesson1-number-red\">1.</span><span>Şimdiki zamanda fiiller</span><span class=\"lesson1-chevron\">⌃</span></summary>\n              <div class=\"lesson1-content\">\n                <div class=\"lesson1-info\">Fiiller ve şimdiki zamanda çekimleri.</div>\n                <div class=\"lesson1-verb-cards\">\n                  <article class=\"lesson1-verb-card\">\n                    <h4><span class=\"lesson1-verb-icon\">♟</span>kommen — gelmek</h4>\n                    <div class=\"lesson1-conjugation\"><span>ich</span><strong>komme</strong><span>ben geliyorum</span><span>du</span><strong>kommst</strong><span>sen geliyorsun</span><span>er / sie</span><strong>kommt</strong><span>o geliyor</span><span>wir</span><strong>kommen</strong><span>biz geliyoruz</span><span>ihr</span><strong>kommt</strong><span>siz geliyorsunuz</span><span>sie / Sie</span><strong>kommen</strong><span>onlar geliyor / Siz geliyorsunuz</span></div>\n                  </article>\n                  <article class=\"lesson1-verb-card\">\n                    <h4><span class=\"lesson1-verb-icon\">♟</span>gehen — gitmek</h4>\n                    <div class=\"lesson1-conjugation\"><span>ich</span><strong>gehe</strong><span>ben gidiyorum</span><span>du</span><strong>gehst</strong><span>sen gidiyorsun</span><span>er / sie</span><strong>geht</strong><span>o gidiyor</span><span>wir</span><strong>gehen</strong><span>biz gidiyoruz</span><span>ihr</span><strong>geht</strong><span>siz gidiyorsunuz</span><span>sie / Sie</span><strong>gehen</strong><span>onlar gidiyor / Siz gidiyorsunuz</span></div>\n                  </article>\n                  <article class=\"lesson1-verb-card\">\n                    <h4><span class=\"lesson1-verb-icon\">♟</span>stehen — durmak, ayakta durmak</h4>\n                    <div class=\"lesson1-conjugation\"><span>ich</span><strong>stehe</strong><span>ben duruyorum</span><span>du</span><strong>stehst</strong><span>sen duruyorsun</span><span>er / sie</span><strong>steht</strong><span>o duruyor</span><span>wir</span><strong>stehen</strong><span>biz duruyoruz</span><span>ihr</span><strong>steht</strong><span>siz duruyorsunuz</span><span>sie / Sie</span><strong>stehen</strong><span>onlar duruyor / Siz duruyorsunuz</span></div>\n                  </article>\n                  <article class=\"lesson1-verb-card\">\n                    <h4><span class=\"lesson1-verb-icon\">♟</span>singen — şarkı söylemek</h4>\n                    <div class=\"lesson1-conjugation\"><span>ich</span><strong>singe</strong><span>ben şarkı söylüyorum</span><span>du</span><strong>singst</strong><span>sen şarkı söylüyorsun</span><span>er / sie</span><strong>singt</strong><span>o şarkı söylüyor</span><span>wir</span><strong>singen</strong><span>biz şarkı söylüyoruz</span><span>ihr</span><strong>singt</strong><span>siz şarkı söylüyorsunuz</span><span>sie / Sie</span><strong>singen</strong><span>onlar şarkı söylüyor / Siz şarkı söylüyorsunuz</span></div>\n                  </article>\n                </div>\n                <section class=\"lesson1-block\">\n                  <h4>Örnekler</h4>\n                  <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Stehst du?<br>Ja, ich stehe.</div><div class=\"kurss-example\">Steht Albert?<br>Ja, er steht.</div><div class=\"kurss-example\">Steht Marta?<br>Ja, sie steht.</div><div class=\"kurss-example\">Wer kommt und singt?<br>Albert und Marta kommen und singen.</div><div class=\"kurss-example\">Geht ihr?<br>Ja, wir gehen.</div><div class=\"kurss-example\">Wer steht und singt?<br>Albert und Marta stehen und singen.</div></div>\n                </section>\n              </div>\n            </details>\n            <details class=\"lesson1-accordion\">\n              <summary><span class=\"lesson1-number lesson1-number-green\">2.</span><span>Kelimeler</span><span class=\"lesson1-chevron\">⌄</span></summary>\n              <div class=\"lesson1-content\">\n                <div class=\"lesson1-info lesson1-vardini-info\"><span class=\"lesson1-info-icon\" aria-hidden=\"true\">i</span><span>Kelimelerin yaklaşık telaffuzu parantez içinde Türk harfleriyle verilmiştir.<br>Bu, sonraki derslerde de geçerlidir.</span></div>\n                <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">wir (viir) — biz</div><div class=\"kurss-example\">“wir” kelimesinde i harfi uzun okunur.</div><div class=\"kurss-example\">kommen (kommen) — gelmek</div><div class=\"kurss-example\">gehen (gee-en) — gitmek</div><div class=\"kurss-example\">stehen (ştee-en) — durmak</div><div class=\"kurss-example\">singen (zingen) — şarkı söylemek</div><div class=\"kurss-example\">du (duu) kommst — sen geliyorsun</div><div class=\"kurss-example\">er (eer) kommt — o (erkek) geliyor</div><div class=\"kurss-example\">sie (zii) kommt — o (kadın) geliyor</div><div class=\"kurss-example\">wer (veer) — kim?</div><div class=\"kurss-example\">ja (yaa) — evet</div></div>\n              </div>\n            </details>\n                        <details class=\"lesson1-accordion\">\n              <summary><span class=\"lesson1-number lesson1-number-purple\">3.</span><span>Telaffuz</span><span class=\"lesson1-chevron\">⌄</span></summary>\n              <div class=\"lesson1-content\">\n                <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Kelimelerin Türk harfleriyle yazılmış doğru telaffuzu derslerde verilmiştir.</div><div class=\"kurss-example\">Wir (viir) — biz. wir kelimesinde i her zaman uzun okunur.</div></div>\n              </div>\n            </details>\n<details class=\"lesson1-accordion\">\n              <summary><span class=\"lesson1-number lesson1-number-blue\">4.</span><span>Dilbilgisi</span><span class=\"lesson1-chevron\">⌄</span></summary>\n              <div class=\"lesson1-content lesson1-grammar-content\">\n                <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>∞</span>Mastar</h4><div class=\"lesson1-grammar-note\">Fiilin temel biçimi. Mastar genellikle -en ile biter.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">kommen</div><div class=\"kurss-example\">gehen</div><div class=\"kurss-example\">stehen</div><div class=\"kurss-example\">singen</div></div></section>\n                <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>♟</span>Şimdiki zaman ekleri</h4><div class=\"lesson1-ending-info\"><span class=\"lesson1-info-icon\" aria-hidden=\"true\">i</span><div class=\"lesson1-ending-info-body\"><p><strong>Fiilin temel biçiminden <span class=\"lesson1-ending-accent\">-en</span> ekini çıkar ve kişi ekini ekle.</strong></p><p>Örnek: kommen → komm + ek</p><div class=\"lesson1-ending-process\" aria-label=\"Şimdiki zaman eklerinin oluşturulması\"><div class=\"lesson1-ending-step\"><strong>kommen</strong><span>temel biçim</span></div><span class=\"lesson1-ending-arrow\">→</span><div class=\"lesson1-ending-step\"><strong>çıkar <span class=\"lesson1-ending-accent\">-en</span></strong><span>kök kalır</span></div><span class=\"lesson1-ending-arrow\">→</span><div class=\"lesson1-ending-step\"><strong>komm</strong><span>kök</span></div><span class=\"lesson1-ending-arrow\">→</span><div class=\"lesson1-ending-step\"><strong>eki ekle</strong><span>e / st / t</span></div><span class=\"lesson1-ending-arrow\">→</span><div class=\"lesson1-ending-results\"><div>komm + <span class=\"lesson1-ending-accent\">e</span> = <strong>komme</strong></div><div>komm + <span class=\"lesson1-ending-accent\">st</span> = <strong>kommst</strong></div><div>komm + <span class=\"lesson1-ending-accent\">t</span> = <strong>kommt</strong></div></div></div></div></div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ich → -e</div><div class=\"kurss-example\">du → -st</div><div class=\"kurss-example\">er / sie → -t</div><div class=\"kurss-example\">wir → -en</div><div class=\"kurss-example\">ihr → -t</div><div class=\"kurss-example\">sie → -en</div></div></section>\n                <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>●</span>Örnekler</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ich komme</div><div class=\"kurss-example\">du kommst</div><div class=\"kurss-example\">er kommt</div><div class=\"kurss-example\">wir kommen</div></div></section>\n                <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>?</span>Soru cümleleri</h4><div class=\"lesson1-grammar-info\"><span class=\"lesson1-info-icon\" aria-hidden=\"true\">i</span><span>Almanca soru cümlesinde fiil genellikle birinci sıraya geçer.</span></div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Türkçede:<br>Sen geliyorsun.<br>Sen geliyor musun?</div><div class=\"kurss-example\">Almancada:<br>Du kommst.<br>Kommst du?</div><div class=\"kurss-example\">du kommst — sen geliyorsun<br>kommst du? — geliyor musun?</div><div class=\"kurss-example\">er singt — o şarkı söylüyor<br>singt er? — o şarkı söylüyor mu?</div></div></section>\n                <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>♣</span>Kişi farkı</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">er kommt — o (erkek) geliyor</div><div class=\"kurss-example\">sie kommt — o (kadın) geliyor</div><div class=\"kurss-example\">sie kommen — onlar geliyor</div></div></section>\n              </div>\n            </details>\n                        <details class=\"lesson1-accordion\">\n              <summary><span class=\"lesson1-number lesson1-number-orange\">5.</span><span>Çevir</span><span class=\"lesson1-chevron\">⌄</span></summary>\n              <div class=\"lesson1-content\">\n                <div class=\"lesson1-training-wrap\">\n                  <button class=\"lesson1-training-flashcard\" type=\"button\" data-lesson1-training-card data-training-index=\"0\" data-showing-back=\"false\" aria-label=\"Ders 1 alıştırma kartı\">\n                    <span class=\"lesson1-training-progress\">Ders 1 · Çevir: 1 / 11</span>\n                    <span class=\"lesson1-training-text\">Geliyor musun?</span>\n                  </button>\n                  <p class=\"lesson1-training-hint\">Almanca çevirisini görmek için karta tıkla. Cevaptan sonra bir sonraki tıklama sonraki kartı gösterir.</p>\n                </div>\n              </div>\n            </details>"
};

